const net = require('net');
const fs = require('fs');
const path = require('path');

// Parse --directory argument
let directory = '/tmp';
const dirIdx = process.argv.indexOf('--directory');
if (dirIdx !== -1) directory = process.argv[dirIdx + 1];

function parseHeaders(request) {
    const lines = request.split('\r\n');
    const headers = {};
    for (let i = 1; i < lines.length; i++) {
        if (lines[i] === '') break;
        const [key, ...rest] = lines[i].split(': ');
        headers[key.toLowerCase()] = rest.join(': ');
    }
    return headers;
}

const server = net.createServer((socket) => {
    socket.on('data', (data) => {
        const request = data.toString();
        const requestLine = request.split('\r\n')[0];
        const [method, urlPath, version] = requestLine.split(' ');
        const headers = parseHeaders(request);

        if (urlPath === '/') {
            socket.write('HTTP/1.1 200 OK\r\n\r\n');
        } else if (urlPath.startsWith('/echo/')) {
            const body = urlPath.slice(6);
            socket.write(
                `HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Length: ${body.length}\r\n\r\n${body}`
            );
        } else if (urlPath === '/user-agent') {
            const body = headers['user-agent'] || '';
            socket.write(
                `HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Length: ${body.length}\r\n\r\n${body}`
            );
        } else if (urlPath.startsWith('/files/')) {
            const filename = urlPath.slice(7);
            const filepath = path.join(directory, filename);
            if (fs.existsSync(filepath) && fs.statSync(filepath).isFile()) {
                const body = fs.readFileSync(filepath);
                socket.write(
                    `HTTP/1.1 200 OK\r\nContent-Type: application/octet-stream\r\nContent-Length: ${body.length}\r\n\r\n`
                );
                socket.write(body);
            } else {
                socket.write('HTTP/1.1 404 Not Found\r\n\r\n');
            }
        } else {
            socket.write('HTTP/1.1 404 Not Found\r\n\r\n');
        }

        socket.end();
    });
});

server.listen(4221, 'localhost', () => {
    console.log(`Serving files from ${directory} on port 4221...`);
});
